def unique(l: list) -> list:
    """Return sorted unique elements in a list

    >>> unique([5, 3, 5, 2, 3, 3, 9, 0, 123])
    [0, 2, 3, 5, 9, 123]
    """
    count_dict = {}
    result = []
    for elem in l:
        if elem in count_dict:
            count_dict[elem] += 1
        else:
            count_dict[elem] = 1
    for key in sorted(count_dict.keys()):
        for _ in range(count_dict[key]):
            result.append(key)
    return result
