def numerical_letter_grade(grades):
    """
    This function takes a list of student GPAs as input and returns a list of corresponding letter grades.

    Parameters:
    grades (list): A list of student GPAs.

    Returns:
    list: A list of corresponding letter grades.

    Example:
    numerical_letter_grade([4.0, 3, 1.7, 2, 3.5]) == ['A+', 'B', 'C-', 'C', 'A-']
    """
    mid_point_1 = 3.7
    mid_point_2 = 2.3
    mid_point_3 = 1.7

    def map_gpa_to_letter_grade(gpa):
        if gpa >= 4.0:
            return 'A+'
        elif gpa >= mid_point_1:
            return 'A'
        elif gpa >= 3.0:
            return 'A-'
        elif gpa >= mid_point_2:
            return 'B'
        elif gpa >= 2.0:
            return 'B-'
        elif gpa >= mid_point_3:
            return 'C'
        elif gpa >= 1.0:
            return 'C-'
        elif gpa >= 0.7:
            return 'D+'
        elif gpa >=0.0:
            return 'D'
        else:
            return 'E'

    return [map_gpa_to_letter_grade(g) for g in grades]
