import re

def split_words(txt):
    '''
    Given a string of words, return a list of words split on whitespace, if no whitespaces exists in the text you
    should split on commas ',' if no commas exists you should return the number of lower-case letters with odd order in the alphabet, 
    ord('a') = 0, ord('b') = 1, ... ord('z') = 25
    Examples
    split_words("Hello world!") == ["Hello", "world!"]
    split_words("Hello,world!") == ["Hello", "world!"]
    split_words("abcdef") == 3 
    '''
    # Check if there are any spaces in the string
    if any(char.isspace() for char in txt):
        # use regular expressions to split the string into a list of words
        return re.findall(r'\S+', txt)
    # If no spaces, use regular expression to split on commas and then process the names
    elif any(char==',' for char in txt):
        # split on commas and strip any leading/trailing commas, and commas that are part of the string
        words = re.findall(r'[^\s,]+', txt)
        # Remove any remaining commas and store as a list of words
        clean_words = [w.replace(',', '') for w in words]
        # Check if it is only one word left
        if len(clean_words) == 1:
            # if it is one word, count odd letters
            counter = 0
            for char in clean_words[0].lower():
                if char.isalpha():
                    if ord(char) % 2 == 1:
                        counter += 1
            return counter
        else:
            # if it is more words, return the clean words
            return clean_words
    else:
        # if neither commas nor spaces, count odd letters
        counter = 0
        for char in txt.lower():
            if char.isalpha():
                if ord(char) % 2 == 1:
                    counter += 1
        return counter
