def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True


def intersection(interval1, interval2):
    """Return 'YES' if the length of the intersection of two intervals is a prime number, 
    'NO' otherwise."""
    start = max(interval1[0], interval2[0])
    end = min(interval1[1], interval2[1])

    intersection_length = end - start + 1

    if start > end:
        return "NO"

    if is_prime(intersection_length):
        return "YES"
    else:
        return "NO"


