def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    Args:
        a (int or float or str): The first value to compare.
        b (int or float or str): The second value to compare.

    Returns:
        int or float or str: The larger value, or None if the values are equal.
    """

    # Check if either value is None
    if a is None or b is None:
        return None

    # Compare integers
    if isinstance(a, int) and isinstance(b, int):
        return None if a == b else max(a, b)

    # Compare floats
    if isinstance(a, float) and isinstance(b, float):
        return None if a == b else max(a, b)

    # Compare strings
    if isinstance(a, str):
        # Remove any comma or decimal point from string representation of a or b
        if isinstance(b, str):
            a = float(a.replace(',', '.'))
            b = float(b.replace(',', '.'))
        else:
            a = float(a.replace(',', '.'))

    # Check if both values are now the same type
    if isinstance(a, float) and isinstance(b, float):
        return None if a == b else max(a, b)

    # If not all above conditions are met, return None
    return None
